INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-30' FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'No domestic B2B mandate — mature B2G regime plus near-universal voluntary B2B adoption', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Finland currently has no confirmed domestic B2B e-invoicing mandate date — this page will be updated if the government''s signalled 2028 preparations produce a firmer timeline. Confirm current requirements directly with Valtiokonttori before building an integration.', 'Finland is a genuine outlier in this tracker: one of Europe''s earliest and most mature e-invoicing environments, yet still without any domestic B2B mandate at all — adoption has simply outpaced regulation.', 'Two long-established national formats, both capable of meeting the European standard — but compliance has to be checked, not assumed.', 'The single most important thing to understand about Finland: outside B2G, nothing here is actually mandatory — but the practical reality is that most businesses use e-invoicing anyway.', 'There''s no registration process to speak of for a mandate that doesn''t exist yet — the practical work here is about capability and verification, not sign-up.', 'There''s no formal fine schedule to report here, because there''s no B2B mandate to enforce — the real consequences of non-adoption are commercial, not statutory.' FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'No B2B', 'mandate — none confirmed');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '~99%', 'B2G invoices already electronic');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2020', 'B2G mandate began');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2030', 'EU ViDA cross-border deadline');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '€10k', 'turnover — right to demand e-invoices');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'National formats', '[["Format 1", "Finvoice 3.0"], ["Format 2", "TEAPPSXML 3.0"], ["EU alignment", "Both can produce EN 16931-compliant output"]]', 'Neither format guarantees EN 16931 compliance automatically — the business or its software provider must verify the actual output meets the standard.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Consolidated invoices', '[["Permitted under EN standard", "No"]]', 'A traditional consolidated invoice charging several orders in one document doesn''t fit the European standard''s row-level structure — a genuine constraint if your current process relies on batching.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No central platform', '[["Routing mechanism", "Verkkolaskuosoite directory"], ["Organisations listed", "300,000+"]]', 'Unlike clearance-model countries with one government platform, Finland routes invoices through whichever operator/portal a given counterparty uses — the directory tells you which one.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Verification support', '[["Software readiness list", "Maintained by TIEKE ry"], ["Operator-side checking", "Some operators verify compliance before transmission"]]', 'Worth confirming whether your specific operator checks EN 16931 compliance for you, or whether that responsibility sits with your own software.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G', '[["Status", "Mandatory"], ["Applies to", "All levels of government"], ["Foreign suppliers", "Must use EN 16931 format"]]', 'This is the one genuinely binding requirement in Finland''s entire regime — everything else described on this page is voluntary or contractual.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B (domestic)', '[["Status", "Voluntary — no mandate"], ["Right to demand", "Turnover above €10,000"], ["Tax authority clearance", "Not required"]]', 'A business can insist on e-invoices from suppliers contractually, and often does — but there''s no legal requirement to issue them at all.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2C', '[["Status", "No mandate"]]', 'Consumers can receive e-invoices via online banking, Suomi.fi Messages, or Posti''s OmaPosti service, but nothing requires a business to offer this.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Intra-EU B2B', '[["Current status", "Not yet subject to any Finnish mandate"], ["Becomes mandatory", "1 July 2030, EU-wide (ViDA)"]]', 'Finland plans to implement at the EU deadline itself, rather than moving ahead of it the way several other countries in this tracker have chosen to.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No B2B penalty framework exists', NULL, NULL, 'Since domestic B2B e-invoicing isn''t mandatory, there''s genuinely no fine or sanction to describe here — a real difference from every clearance or CTC-model country in this tracker.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The real risk is commercial, not legal', NULL, NULL, 'A business that can''t send e-invoices risks losing out to competitors on contracts with counterparties who demand it — especially larger businesses exercising their statutory right under the 2019 Act.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G non-compliance is the one real exception', NULL, NULL, 'Failing to send e-invoices to a Finnish government body isn''t a matter of choice — this is the one place Finland''s regime genuinely functions like a mandate.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Watch the 2028 preparation window closely', NULL, NULL, 'Given no domestic B2B date is set, the government''s own signalled 2028 preparations are the most concrete early indicator of what might come before the 2030 EU deadline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply any Finnish public-sector body, confirm e-invoicing capability now', 'This has been the norm since 2020 — it''s not a new requirement, and public buyers will expect it as a baseline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Verify your Finvoice 3.0 or TEAPPSXML 3.0 output is genuinely EN 16931-compliant', 'Check TIEKE ry''s readiness list for your software, or confirm your operator verifies compliance before transmission.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Use the Verkkolaskuosoite directory to find the right routing for each counterparty', 'There''s no single platform — this directory tells you which operator or portal actually reaches a given organisation.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'For domestic B2B, check your specific customers'' contractual requirements', 'Don''t assume a legal mandate exists just because e-invoicing is widespread — confirm what''s actually required by the counterparties you deal with.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Revisit this page periodically ahead of 2028', 'Finland''s government has signalled ViDA preparations beginning around 2028 — a firmer domestic timeline could emerge well before the 2030 EU deadline itself.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.valtiokonttori.fi/en/e-invoicing-fast-and-safe/', 0 FROM countries WHERE name_en = 'Finland';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Valtiokonttori (Finnish State Treasury) — e-invoicing');
